package com.studentassignment.api;
import com.studentassignment.model.Assignment;import com.studentassignment.security.UserContext;import com.studentassignment.service.*;import java.util.*;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/assignments") public class AssignmentController {
 private final AssignmentService service;private final UserContext context;private final FileStorageService files;public AssignmentController(AssignmentService service,UserContext context,FileStorageService files){this.service=service;this.context=context;this.files=files;}
 @GetMapping public Map<String,Object> list(@RequestParam(required=false)String subject){return Map.of("data",service.list(subject).stream().map(Views::assignment).toList());}
 @GetMapping("/faculty") @PreAuthorize("hasRole('FACULTY')") public Map<String,Object> faculty(Authentication auth){return Map.of("data",service.faculty(context.id(auth)).stream().map(Views::assignment).toList());}
 @GetMapping("/{id}") public Map<String,Object> get(@PathVariable Long id){return Map.of("data",Views.assignment(service.get(id)));}
 @PostMapping(value="/create",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('FACULTY')") public Map<String,Object> create(@RequestParam String title,@RequestParam(required=false)String description,@RequestParam String subject,@RequestParam(defaultValue="100")Integer maxMarks,@RequestParam java.time.LocalDateTime deadline,@RequestPart(required=false)MultipartFile file,Authentication auth){return Map.of("data",Views.assignment(service.create(title,description,subject,maxMarks,deadline,file,context.id(auth))));}
 @PutMapping(value="/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('FACULTY')") public Map<String,Object> update(@PathVariable Long id,@RequestParam String title,@RequestParam(required=false)String description,@RequestParam String subject,@RequestParam(required=false)Integer maxMarks,@RequestParam java.time.LocalDateTime deadline,@RequestPart(required=false)MultipartFile file,Authentication auth){return Map.of("data",Views.assignment(service.update(id,title,description,subject,maxMarks,deadline,file,context.id(auth))));}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('FACULTY')") public Map<String,Object> delete(@PathVariable Long id,Authentication auth){service.delete(id,context.id(auth));return Map.of("message","Assignment deleted successfully.");}
 @GetMapping("/{id}/download") public ResponseEntity<Resource> download(@PathVariable Long id){Assignment a=service.get(id);if(a.getInstructionFilePath()==null)throw ApiException.notFound("Instruction file not found.");return download(files.load(a.getInstructionFilePath()),a.getInstructionFileName());}
 private ResponseEntity<Resource> download(Resource resource,String name){return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(name).build().toString()).body(resource);}
}
